mapper.select:
select c.id as id, c.member_id as memberId, m.nickname as memberNickname, c.reason as reason, c.status as status, c.review_note as reviewNote, c.reviewer_user_id as reviewerUserId, c.review_time as reviewTime, c.create_time as createTime, (c.old_id_card_hash is not null and c.old_id_card_hash = c.id_card_hash) as sameIdCard, exists (select 1 from ums_member_identity other where other.id_card_hash = c.id_card_hash and other.member_id <> c.member_id) as idCardBoundElsewhere from ums_member_identity_change c left join ums_member m on m.id = c.member_id
and c.status = #{status}
order by c.create_time desc, c.id desc
